.bubble-them-custom {
  background: #e2e2e2 !important;
  color: #333333 !important;

  border: none !important;
  border-width: 0 !important;
  border-radius: 8px !important;
  box-shadow: none !important;

  padding: 9px 13px !important;
  font-size: 13px !important;

  margin-bottom: 3px !important;
}

/* 我方气泡 */
.bubble-me-custom {
  background: #f1f1f1 !important;
  color: #333333 !important;

  border: none !important;
  border-width: 0 !important;
  border-radius: 8px !important;
  box-shadow: none !important;

  padding: 9px 13px !important;
  font-size: 13px !important;

  margin-bottom: 3px !important;
}


/* ================================================================
   双方文字统一深灰
================================================================ */

.bubble-them-custom *,
.bubble-me-custom * {
  color: #333333 !important;
  -webkit-text-fill-color: #333333 !important;
}


/* ================================================================
   每条消息都显示头像
================================================================ */

.msg-avatar-them-container,
.msg-avatar-me-container {
  visibility: visible !important;
}


/* ================================================================
   图片消息：整个容器缩小到 75%
================================================================ */

/* 图片容器 */
.msg-image-wrapper {
  width: 75% !important;
  max-width: 75% !important;
  height: auto !important;

  margin: 0 !important;

  background: transparent !important;
  border: none !important;
  border-width: 0 !important;
  box-shadow: none !important;
}

/* 图片本身跟随容器 */
.msg-image-wrapper img {
  width: 100% !important;
  height: auto !important;
  display: block !important;

  border: none !important;
  border-width: 0 !important;
  box-shadow: none !important;
}


/* ================================================================
   我方图片靠右
================================================================ */

.msg-me .msg-image-wrapper {
  margin-left: auto !important;
  margin-right: 0 !important;
}


/* ================================================================
   图片消息取消外层气泡
================================================================ */

.bubble-them-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(.msg-image-wrapper) {
  background: transparent !important;
  border: none !important;
  border-width: 0 !important;
  box-shadow: none !important;
}


/* ================================================================
   彻底取消气泡伪元素边框
================================================================ */

.bubble-them-custom::before,
.bubble-them-custom::after,
.bubble-me-custom::before,
.bubble-me-custom::after {
  border: none !important;
  box-shadow: none !important;
}

